// Generated by Manus asset storage.
import { createHash } from 'node:crypto'
import { appendFileSync, constants, existsSync, lstatSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

export const ASSET_UPLOAD_JOURNAL = 'dist/.asset-upload-journal.jsonl'
const digest = content => createHash('sha256').update(content).digest('hex')
function journalPath(root) {
  const dist = join(root, 'dist')
  if (existsSync(dist) && (!lstatSync(dist).isDirectory() || lstatSync(dist).isSymbolicLink())) {
    throw new Error('dist must be a project directory')
  }
  return join(root, ASSET_UPLOAD_JOURNAL)
}

// The canonical manifest stays JSON. This local journal only bridges an upload
// batch, including process termination before the manifest is published.
export function readAssetUploadJournal(root, manifestContent) {
  const path = journalPath(root)
  if (!existsSync(path)) return []
  if (!lstatSync(path).isFile() || lstatSync(path).isSymbolicLink()) throw new Error('Invalid asset upload journal')
  const content = readFileSync(path, 'utf8')
  // A killed append can leave an incomplete last record; earlier records stand.
  const end = content.lastIndexOf('\n')
  if (end < 0) return []
  const [first, ...lines] = content.slice(0, end).split('\n')
  const header = JSON.parse(first)
  if (header?.version !== 1 || typeof header.baseDigest !== 'string') throw new Error('Invalid asset upload journal')
  // A completed rename, an asset edit, or a checkout supersedes this batch.
  if (header.baseDigest !== digest(manifestContent)) return []
  return lines.map(line => {
    const record = JSON.parse(line)
    if (!record || typeof record.rel !== 'string' || !record.entry) throw new Error('Invalid asset upload record')
    return [record.rel, record.entry]
  })
}

export function startAssetUploadJournal(root, manifestContent) {
  writeFileSync(journalPath(root), `${JSON.stringify({ version: 1, baseDigest: digest(manifestContent) })}\n`,
    { flag: 'wx' })
}

export function recordAssetUpload(root, rel, entry) {
  appendFileSync(journalPath(root), `${JSON.stringify({ rel, entry })}\n`,
    { flag: constants.O_WRONLY | constants.O_APPEND | constants.O_NOFOLLOW })
}

export function clearAssetUploadJournal(root) {
  rmSync(journalPath(root), { force: true })
}
